import { createRouter, createWebHistory, type RouteRecordRaw } from 'vue-router'

import { setupGuards } from './guards'
import type { SystemCapabilities } from '@/types'

declare module 'vue-router' {
  interface RouteMeta {
    title?: string
    requiresAuth?: boolean
    guestOnly?: boolean
    /** 后端能力关闭时守卫会退回对话页，不在 M1 请求未注册端点。 */
    capability?: keyof SystemCapabilities
  }
}

export const routes: RouteRecordRaw[] = [
  {
    path: '/login',
    name: 'login',
    component: () => import('@/views/auth/LoginView.vue'),
    meta: { title: '登录', guestOnly: true },
  },
  {
    path: '/register',
    name: 'register',
    component: () => import('@/views/auth/RegisterView.vue'),
    meta: { title: '注册', guestOnly: true },
  },
  {
    path: '/',
    component: () => import('@/layouts/AppLayout.vue'),
    meta: { requiresAuth: true },
    children: [
      { path: '', redirect: { name: 'chat' } },
      {
        path: 'chat',
        name: 'chat',
        component: () => import('@/views/chat/ChatView.vue'),
        meta: { title: '对话' },
      },
      {
        path: 'workflows',
        name: 'workflows',
        component: () => import('@/views/WorkflowsView.vue'),
        meta: { title: '工作流', capability: 'workflows' },
      },
      {
        path: 'agents',
        name: 'agents',
        component: () => import('@/views/AgentsView.vue'),
        meta: { title: '智能体', capability: 'agents' },
      },
      {
        path: 'tasks',
        name: 'tasks',
        component: () => import('@/views/TasksView.vue'),
        meta: { title: '任务', capability: 'tasks' },
      },
      {
        path: 'knowledge',
        name: 'knowledge',
        component: () => import('@/views/KnowledgeView.vue'),
        meta: { title: '知识库', capability: 'knowledge' },
      },
      {
        path: 'settings',
        name: 'settings',
        component: () => import('@/views/SettingsView.vue'),
        meta: { title: '设置' },
      },
    ],
  },
  {
    path: '/:pathMatch(.*)*',
    name: 'not-found',
    component: () => import('@/views/NotFoundView.vue'),
    meta: { title: '页面不存在' },
  },
]

const router = createRouter({
  history: createWebHistory(import.meta.env.BASE_URL),
  routes,
})

setupGuards(router)

export default router

import { computed, ref } from 'vue'
import { defineStore } from 'pinia'

import { authApi } from '@/api/auth'
import type { AuthTokens, RegisterRequest, User } from '@/types'
import { storage } from '@/utils/storage'

export const useAuthStore = defineStore('auth', () => {
  const user = ref<User | null>(null)
  const accessToken = ref<string | null>(storage.getAccessToken())
  const initialized = ref(false)

  const isAuthenticated = computed(() => Boolean(accessToken.value))

  function setSession(tokens: AuthTokens): void {
    storage.setTokens(tokens)
    accessToken.value = tokens.access_token
  }

  function setUser(next: User | null): void {
    user.value = next
  }

  function clearSession(): void {
    storage.clearTokens()
    accessToken.value = null
    user.value = null
  }

  async function login(email: string, password: string): Promise<User> {
    const tokens = await authApi.login({ email, password })
    setSession(tokens)
    const profile = await authApi.me()
    setUser(profile)
    initialized.value = true
    return profile
  }

  async function register(body: RegisterRequest): Promise<User> {
    const tokens = await authApi.register(body)
    setSession(tokens)
    const profile = await authApi.me()
    setUser(profile)
    initialized.value = true
    return profile
  }

  async function restore(): Promise<void> {
    if (initialized.value) return
    if (!storage.getAccessToken()) {
      initialized.value = true
      return
    }
    try {
      accessToken.value = storage.getAccessToken()
      user.value = await authApi.me()
    } catch {
      clearSession()
    } finally {
      initialized.value = true
    }
  }

  async function logout(): Promise<void> {
    try {
      await authApi.logout()
    } catch {
      // 后端不可达时也必须完成本地登出。
    } finally {
      clearSession()
      initialized.value = true
    }
  }

  return {
    user,
    accessToken,
    initialized,
    isAuthenticated,
    login,
    register,
    restore,
    logout,
    setUser,
    clearSession,
  }
})
